def t(k):
    while k % 2 == 0:
        k //= 2
    return k

def f(k):
    return t(k) % 4

# Precompute f for a large range
N = 300000
F = [0] * (N + 1)
for k in range(1, N + 1):
    F[k] = f(k)

# Check all a up to 200, search n up to N-2a
for a in range(1, 201):
    found = None
    limit = N - 2*a
    for n in range(1, limit + 1):
        ok = True
        for i in range(a):
            if F[n+i] != F[n+a+i]:
                ok = False
                break
        if ok:
            found = n
            break
    if found is not None:
        print(f"a={a}: n={found}")
EOF
python3 /tmp/explore3.py
